package javiertorres.amazonconbackend22settembre.config;
import javiertorres.amazonconbackend22settembre.entity.Utente; import javiertorres.amazonconbackend22settembre.repository.UtenteRepository; import javiertorres.amazonconbackend22settembre.security.JwtAuthFilter; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.userdetails.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
@Configuration @EnableMethodSecurity public class SecurityConfig { @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean UserDetailsService userDetailsService(UtenteRepository repo){return email->repo.findByEmailIgnoreCase(email).map(this::details).orElseThrow(()->new UsernameNotFoundException(email));} private UserDetails details(Utente u){return org.springframework.security.core.userdetails.User.withUsername(u.getEmail()).password(u.getPassword()).disabled(!u.isEnabled()).authorities(u.getRoles().stream().map(r->"ROLE_"+r.getName()).toArray(String[]::new)).build();} @Bean SecurityFilterChain securityFilterChain(HttpSecurity http,JwtAuthFilter filter)throws Exception{return http.cors(org.springframework.security.config.Customizer.withDefaults()).csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/error").permitAll().requestMatchers(org.springframework.http.HttpMethod.GET,"/api/oggetti/**").permitAll().anyRequest().authenticated()).addFilterBefore(filter,UsernamePasswordAuthenticationFilter.class).build();} }
